func show_line(speaker: String, text: String) -> void:
	if speaker_label:
		speaker_label.text = speaker

	if text_label:
		var parsed_data := _parse_wait_tags(text)
		var clean_text: String = parsed_data["text"]
		var custom_pauses: Dictionary = parsed_data["pauses"]

		text_label.text = clean_text
		text_label.visible_characters = 0

		var parsed_text: String = text_label.get_parsed_text()
		var total_chars: int = parsed_text.length()

		for i in range(total_chars):
			text_label.visible_characters = i + 1
			var current_char: String = parsed_text[i]

			if custom_pauses.has(i + 1):
				var wait_duration: float = float(custom_pauses[i + 1])
				await get_tree().create_timer(wait_duration).timeout
			elif current_char in [".", "!", "?"]:
				await get_tree().create_timer(0.3).timeout
			elif current_char == ",":
				await get_tree().create_timer(0.15).timeout
			else:
				await get_tree().create_timer(0.03).timeout

	line_finished.emit()


func _parse_wait_tags(raw_text: String) -> Dictionary:
	var regex := RegEx.new()
	regex.compile("\\{wait=([0-9.]+)\\}")

	var pauses := {}
	var clean_text := ""
	var last_index := 0

	var matches := regex.search_all(raw_text)
	for m in matches:
		var start := m.get_start()
		clean_text += raw_text.substr(last_index, start - last_index)
		var duration := float(m.get_string(1))
		pauses[clean_text.length()] = duration
		last_index = m.get_end()

	clean_text += raw_text.substr(last_index)
	return {"text": clean_text, "pauses": pauses}


func clear() -> void:
	if speaker_label:
		speaker_label.text = ""
	if text_label:
		text_label.text = ""
		text_label.visible_characters = -1
